// Sample packages in public/samples (generated by scripts/gen_packages.py), shared by the API routes and the UI.
export const SAMPLES = {
  's1-clean': { label: 'Clean package', hint: 'All three documents agree — ready to approve' },
  's2-errors': { label: 'Unit-price gap + wrong VAT', hint: 'Errors are on the invoice — a corrected version is bundled for the fix loop' },
  's3-risky': { label: 'Wrong tax ID + wrong date + harsh penalty', hint: 'High risk, several kinds of violation' },
} as const;

/** Bundled corrected documents for a sample package (the fix loop in demo mode). */
export const SAMPLE_FIXES: Partial<Record<SampleId, { dir: string; files: { type: 'invoice' | 'invoiceXml'; name: string }[] }>> = {
  's2-errors': { dir: 's2-fixed', files: [{ type: 'invoice', name: 'invoice.pdf' }, { type: 'invoiceXml', name: 'invoice.xml' }] },
};

export type SampleId = keyof typeof SAMPLES;
export const SAMPLE_IDS = Object.keys(SAMPLES) as [SampleId, ...SampleId[]];
